import{_ as a,c as t,o as i,a2 as o}from"./chunks/framework.bjzS3PU6.js";const p=JSON.parse('{"title":"The Bloc","description":"","frontmatter":{},"headers":[],"relativePath":"entries/organizations/The-Bloc.md","filePath":"entries/organizations/The-Bloc.md"}'),r={name:"entries/organizations/The-Bloc.md"};function n(s,e,l,c,h,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="the-bloc" tabindex="-1">The Bloc <a class="header-anchor" href="#the-bloc" aria-label="Permalink to &quot;The Bloc&quot;">​</a></h1><hr><p><strong>TYPE</strong>: Underground activist organization<br><strong>ESTABLISHED</strong>: 1999<br><strong>LOCATION</strong>: Saint Juniper, California<br><strong>HEADQUARTERS</strong>: <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a><br><strong>STATUS</strong>: Active</p><hr><p><strong>The Bloc</strong> is an underground activist organization based in Saint Juniper, California that investigates and exposes alleged illegal research operations conducted by the <a href="./Miter-Corporation">Miter Corporation</a> at the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a>. Founded in 1999 by three computer security researchers, the organization has gained prominence for recovering classified documents, infiltrating secure networks, and adopting escaped subject <a href="./../subjects/G-BOY">G*BOY</a> (designation G-304) as their symbol of resistance.</p><p><strong>At a glance</strong></p><ul><li>Underground activist organization investigating Miter Corporation research programs</li><li>Founded 1999 by <a href="./../people/Z-L1NE">Z*L1NE</a>, <a href="./../people/1NK">1NK</a>, and <a href="./../people/GUMM1">GUMM1</a></li><li>Headquarters in basement of St. Juniper Paranormal Museum</li><li>Published <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999)</li><li>Specializes in network infiltration, document recovery, and broadcast hijacking</li><li>Adopted G-304 escape as symbol of resistance against corporate &quot;Harmony&quot; program</li><li>Active membership includes computer security specialists and researchers</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Bloc operates as a watchdog organization focused on exposing what it characterizes as illegal human experimentation programs involving subjects designated with &quot;G-&quot; prefixes. The group formed following the discovery of classified <a href="./Miter-Corporation">Miter Corporation</a> files revealing alleged psychic research programs and human trials conducted at facilities near <a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a>.</p><p>The organization gained public attention following the escape of Subject G-304 from the Saint Juniper Research Campus. The Bloc successfully hijacked facility communications to warn subjects of impending recapture operations and has released recovered internal documents detailing experimental protocols and subject trials.</p><p>According to materials published by The Bloc, the organization views <a href="./Miter-Corporation">Miter Corporation</a> as part of a larger network they call &quot;Harmony&quot;—a program they allege pursues &quot;sedation, unification, homogeny, and control&quot; through corporate and pharmaceutical means.</p><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><h3 id="origins-and-formation" tabindex="-1">Origins and formation <a class="header-anchor" href="#origins-and-formation" aria-label="Permalink to &quot;Origins and formation&quot;">​</a></h3><p>The Bloc&#39;s origins trace to the late 1990s when one of its founding members gained unauthorized access to Miter Corporation secure file storage systems. The materials obtained indicated research programs focused on human cognitive enhancement and what The Bloc characterized as psychic experimentation.</p><p>Following the disappearance of <a href="./../people/Kai-Shepherd">Kai Shepherd</a> at <a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a> in October 1995, <a href="./../people/Z-L1NE">Z*L1NE</a> (real name Rosaline)—a witness to the incident—began conducting independent research at the <a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a>, an occult bookshop operated by <a href="./../people/Magdalena">Magdalena</a>. At the museum, she met two individuals who identified as hackers—<a href="./../people/1NK">1NK</a> and <a href="./../people/GUMM1">GUMM1</a>—who claimed to have discovered evidence of corporate research activities involving child abduction and experimentation.</p><p>The three began collaborating on research throughout the summer, and their investigation attracted additional members. As the group expanded, Magdalena provided basement space at the museum for their operations. In 1999, the collective formally adopted the name &quot;The Bloc&quot; and established the museum basement as their headquarters.</p><h3 id="publication-of-g-boy-manifesto" tabindex="-1">Publication of G*BOY Manifesto <a class="header-anchor" href="#publication-of-g-boy-manifesto" aria-label="Permalink to &quot;Publication of G*BOY Manifesto&quot;">​</a></h3><p>In 1999, the founding members published their core document, <em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion*. The manifesto outlined their philosophy of resistance against what they termed &quot;coercive homogeny&quot; and identified the Harmony Program as a coordinated effort by multiple corporations toward &quot;sedation, unification, homogeny, and control.&quot;</p><p>The document established The Bloc&#39;s decentralized organizational structure: &quot;The Bloc is many. The Bloc is not one thing... We are self governing. Our only goal is to awaken the drones to their true nature through reflecting back to them the secret orchestration of their unique soul&#39;s demise.&quot;</p><p>The manifesto also established the red-hooded figure as The Bloc&#39;s identifying symbol, stating: &quot;Our only identifying feature is the red-eared-hood.&quot;</p><h3 id="failed-infiltration-operation" tabindex="-1">Failed infiltration operation <a class="header-anchor" href="#failed-infiltration-operation" aria-label="Permalink to &quot;Failed infiltration operation&quot;">​</a></h3><p>In the early 2000s, The Bloc organized an operation in which volunteers attempted to infiltrate Miter facilities by allowing themselves to be recruited as research subjects. The operation was intended to gather intelligence from inside the facilities and potentially aid those already held there.</p><p>However, the volunteers underwent what The Bloc describes as &quot;cognitive assessments,&quot; received badges, and had their memories completely erased. According to The Bloc&#39;s account, the volunteers forgot their families, personal histories, and all connections to the organization. They were reduced to what The Bloc characterizes as &quot;weapons&quot; with no other identity.</p><p>The failed operation created what The Bloc describes as a &quot;dark time&quot; for the organization, as members felt responsible for dooming their volunteers to the same fate as those they sought to rescue.</p><h3 id="g-304-escape-and-adoption-of-g-boy-symbol" tabindex="-1">G-304 escape and adoption of G*BOY symbol <a class="header-anchor" href="#g-304-escape-and-adoption-of-g-boy-symbol" aria-label="Permalink to &quot;G-304 escape and adoption of G*BOY symbol&quot;">​</a></h3><p>The escape of Subject G-304 from the Saint Juniper Research Campus provided renewed purpose for The Bloc. The organization obtained footage from internal security cameras showing the red-hooded figure breaking out of the facility. The escape demonstrated that subjects could overcome facility protocols and containment measures.</p><p>The Bloc adopted G-304—whom they designated &quot;G<em>BOY&quot; (replacing the dash with an asterisk)—as their symbol of resistance. Members spread G</em>BOY imagery throughout Saint Juniper through street art, jacket patches, and stickers, transforming the escaped subject into an icon of rebellion against corporate control.</p><p><a href="./../people/Magdalena">Magdalena</a> revealed that G<em>BOY imagery appeared in ancient texts and artifacts within her collection, suggesting the figure corresponded to archetypal symbolism existing across multiple historical and cultural contexts. An ancient statue in the museum&#39;s collection depicted a hooded figure matching G</em>BOY&#39;s appearance, though its presence was disputed among members.</p><h3 id="ritual-and-mystical-operations" tabindex="-1">Ritual and mystical operations <a class="header-anchor" href="#ritual-and-mystical-operations" aria-label="Permalink to &quot;Ritual and mystical operations&quot;">​</a></h3><p>According to The Bloc&#39;s account, <a href="./../people/Magdalena">Magdalena</a> instructed the organization in ritual practices using badges obtained from the facilities. She indicated that by focusing collective energy on <a href="./../subjects/G-BOY">G*BOY</a> &quot;at the right time,&quot; they could not directly save their captured volunteers but could &quot;give them the power to save themselves.&quot;</p><p>The Bloc performed this ritual, which members report was successful in empowering subjects to resist. However, recovered accounts suggest the ritual had unintended dimensional effects—what sources describe as &quot;a tear in the realities.&quot; This dimensional rift reportedly caused <a href="./../subjects/G-BOY">G*BOY</a> to be displaced into <a href="./../locations/Shinkai-Metropolis">Shinkai Metropolis</a>, a mind place within the Mindverse network, where G*BOY appeared as an unwanted &quot;anomaly.&quot;</p><p>The full effects of the ritual and its relationship to consciousness-based phenomena explored at the <a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> remain unclear in recovered documentation.</p><h2 id="structure-and-operations" tabindex="-1">Structure and operations <a class="header-anchor" href="#structure-and-operations" aria-label="Permalink to &quot;Structure and operations&quot;">​</a></h2><h3 id="organizational-philosophy" tabindex="-1">Organizational philosophy <a class="header-anchor" href="#organizational-philosophy" aria-label="Permalink to &quot;Organizational philosophy&quot;">​</a></h3><p>The Bloc operates on decentralized principles, with no formal hierarchy beyond founding members. The organization describes itself as &quot;self governing&quot; and emphasizes individual autonomy within collective action. Members adopt pseudonyms and online handles to maintain operational security.</p><p>The organization&#39;s stated mission focuses on &quot;awakening&quot; individuals to what they characterize as hidden corporate manipulation and control mechanisms, rather than direct confrontation or violence.</p><h3 id="technical-capabilities" tabindex="-1">Technical capabilities <a class="header-anchor" href="#technical-capabilities" aria-label="Permalink to &quot;Technical capabilities&quot;">​</a></h3><p>The Bloc specializes in:</p><ul><li><strong>Network infiltration</strong>: Gaining unauthorized access to secure corporate networks and messaging systems</li><li><strong>Document recovery</strong>: Obtaining classified materials from institutional databases</li><li><strong>Communications security</strong>: Penetrating operational messaging layers and secure communications</li><li><strong>Broadcast hijacking</strong>: Interrupting and overtaking facility communications systems</li><li><strong>Data analysis</strong>: Processing and interpreting recovered materials</li><li><strong>Cryptography</strong>: Breaking security protocols and accessing protected systems</li></ul><h3 id="headquarters-and-facilities" tabindex="-1">Headquarters and facilities <a class="header-anchor" href="#headquarters-and-facilities" aria-label="Permalink to &quot;Headquarters and facilities&quot;">​</a></h3><p>The organization maintains its primary operations in the basement of the St. Juniper Paranormal Museum. The workspace features research tables, computer workstations, extensive book collections, and equipment for technical operations. The space functions as a combination library, workshop, and meeting facility.</p><p>The basement location provides both operational security and access to Magdalena&#39;s collection of occult texts and historical materials relevant to The Bloc&#39;s research.</p><h2 id="known-members" tabindex="-1">Known members <a class="header-anchor" href="#known-members" aria-label="Permalink to &quot;Known members&quot;">​</a></h2><h3 id="founding-members-1999" tabindex="-1">Founding members (1999) <a class="header-anchor" href="#founding-members-1999" aria-label="Permalink to &quot;Founding members (1999)&quot;">​</a></h3><ul><li><strong><a href="./../people/Z-L1NE">Z*L1NE</a></strong> (Rosaline, commonly known as Rozz) — Communications security specialist; responsible for network infiltration and broadcast operations; co-author of <em>G</em>BOY Manifesto*</li><li><strong><a href="./../people/1NK">1NK</a></strong> (also known as Ink) — Computer security researcher; gained initial access to Miter Corporation systems; specializes in network penetration; co-author of <em>G</em>BOY Manifesto*</li><li><strong><a href="./../people/GUMM1">GUMM1</a></strong> (also known as Gummi or Gummy) — Data analysis specialist; processes recovered materials; co-author of <em>G</em>BOY Manifesto*; family member allegedly affected by Harmony Program</li></ul><h3 id="other-active-members" tabindex="-1">Other active members <a class="header-anchor" href="#other-active-members" aria-label="Permalink to &quot;Other active members&quot;">​</a></h3><p>Additional members identified through recovered communications and community activities include:</p><ul><li><strong>synthmilk</strong> (also appearing as <strong>synthmi1k</strong>) — Active in community discussions; shared imagery of facility destruction</li><li><strong>w0rmb4by</strong> — Participated in secure laboratory access operations</li><li><strong>P0ST_M0D3M</strong> — Tracked G*BOY location following escape</li><li><strong>X1U</strong> — Involved in network security operations</li><li><strong>b0ngb0t</strong> — Community member; expressed connection to lost volunteers</li><li><strong>h3xm0m</strong> — Active in community support and communications</li><li><strong>m00nw1tch</strong> — Shared G*BOY community artwork</li><li><strong>0LDbYTE</strong> — Contributed to community discussions</li><li><strong>PR0XY4NG3L</strong> — Provided security warnings to members under surveillance</li></ul><h3 id="associate-and-supporters" tabindex="-1">Associate and supporters <a class="header-anchor" href="#associate-and-supporters" aria-label="Permalink to &quot;Associate and supporters&quot;">​</a></h3><ul><li><strong><a href="./../people/Magdalena">Magdalena</a></strong> — Proprietor of St. Juniper Paranormal Museum; provides headquarters space, resources, and occult guidance; mentor to founding members</li><li><strong>Unnamed volunteers</strong> — Multiple members who volunteered for infiltration operation in early 2000s; underwent memory erasure and remain at facilities with no memory of prior lives</li></ul><h2 id="notable-operations-and-activities" tabindex="-1">Notable operations and activities <a class="header-anchor" href="#notable-operations-and-activities" aria-label="Permalink to &quot;Notable operations and activities&quot;">​</a></h2><h3 id="document-recovery-operations" tabindex="-1">Document recovery operations <a class="header-anchor" href="#document-recovery-operations" aria-label="Permalink to &quot;Document recovery operations&quot;">​</a></h3><p>The Bloc has obtained and published multiple categories of internal Miter Corporation materials:</p><ul><li>Internal memos regarding facility operations and corporate partnerships</li><li>Experiment logs detailing Variable-G trials and subject protocols</li><li>Staff journals from facility personnel</li><li>Surveillance footage from facility security systems</li><li>Intake reports and subject assessment documents</li><li>Communications regarding containment and recapture operations</li></ul><p>Materials are typically attributed as &quot;recovered by The Bloc&quot; or &quot;obtained by activist researchers&quot; when cited in public documentation.</p><h3 id="broadcast-hijacking" tabindex="-1">Broadcast hijacking <a class="header-anchor" href="#broadcast-hijacking" aria-label="Permalink to &quot;Broadcast hijacking&quot;">​</a></h3><p>In December 2025, Z<em>L1NE successfully hijacked a video transmission by <a href="./../people/Dr-M-Ravel">Dr. M. Ravel</a>, a senior researcher at the Saint Juniper Research Campus. Dr. Ravel had been addressing facility subjects about containment operations when Z</em>L1NE interrupted the broadcast to deliver a warning. The incident demonstrated The Bloc&#39;s capabilities in penetrating secure institutional communications.</p><h3 id="network-infiltration" tabindex="-1">Network infiltration <a class="header-anchor" href="#network-infiltration" aria-label="Permalink to &quot;Network infiltration&quot;">​</a></h3><p>The Bloc gained unauthorized access to sj-securelab.net, a private network operated by the Saint Juniper Research Campus. Members penetrated operational messaging systems and obtained lists of facility &quot;operatives,&quot; security flags, and internal communications protocols.</p><h3 id="community-outreach-and-memetic-warfare" tabindex="-1">Community outreach and memetic warfare <a class="header-anchor" href="#community-outreach-and-memetic-warfare" aria-label="Permalink to &quot;Community outreach and memetic warfare&quot;">​</a></h3><p>Following G-304&#39;s escape, The Bloc engaged in widespread distribution of G*BOY imagery throughout Saint Juniper and online communities. Activities included:</p><ul><li>Street art and murals featuring G*BOY iconography</li><li>Distribution of stickers and patches with red-hooded figure imagery</li><li>Creation and sharing of digital artwork celebrating G*BOY</li><li>Publication of manifesto materials linking G*BOY to resistance against &quot;Harmony&quot;</li><li>Community forums discussing facility operations and subject whereabouts</li></ul><h2 id="controversies-and-allegations" tabindex="-1">Controversies and allegations <a class="header-anchor" href="#controversies-and-allegations" aria-label="Permalink to &quot;Controversies and allegations&quot;">​</a></h2><h3 id="volunteer-infiltration-failure" tabindex="-1">Volunteer infiltration failure <a class="header-anchor" href="#volunteer-infiltration-failure" aria-label="Permalink to &quot;Volunteer infiltration failure&quot;">​</a></h3><p>The Bloc&#39;s early 2000s operation to infiltrate Miter facilities by having volunteers allow themselves to be abducted resulted in complete memory erasure for participants. Critics and The Bloc itself acknowledge that the operation placed members in danger without adequate preparation for the facility&#39;s capabilities.</p><p>The Bloc maintains that the volunteers understood the risks but that the organization underestimated the thoroughness of memory erasure procedures. The fate of these volunteers—now serving as facility subjects with no memory of their former lives or mission—remains a point of guilt and motivation for continuing operations.</p><h3 id="harassment-allegations" tabindex="-1">Harassment allegations <a class="header-anchor" href="#harassment-allegations" aria-label="Permalink to &quot;Harassment allegations&quot;">​</a></h3><p>The Bloc has claimed that members, particularly Z*L1NE, have been targeted with psychological deterrence measures by unidentified parties. The organization alleged that members conducting online research received threatening messages intended to dissuade investigative activities.</p><p>No law enforcement investigation was opened regarding these claims, and the allegations remain unverified by independent sources.</p><h3 id="miter-corporation-characterization" tabindex="-1">Miter Corporation characterization <a class="header-anchor" href="#miter-corporation-characterization" aria-label="Permalink to &quot;Miter Corporation characterization&quot;">​</a></h3><p>Miter Corporation representatives have referred to The Bloc as a &quot;baffled group of cryptocurrency hackers&quot; spreading misinformation. The corporation disputes The Bloc&#39;s characterization of facility operations and subject treatment.</p><p>The Bloc&#39;s claims regarding the Harmony Program—described as a network of corporations pursuing mass sedation and control—have not been independently verified. The organization&#39;s sources consist primarily of materials it describes as recovered or leaked documents, which independent parties have not authenticated.</p><h2 id="philosophy-and-ideology" tabindex="-1">Philosophy and ideology <a class="header-anchor" href="#philosophy-and-ideology" aria-label="Permalink to &quot;Philosophy and ideology&quot;">​</a></h2><h3 id="opposition-to-harmony" tabindex="-1">Opposition to &quot;Harmony&quot; <a class="header-anchor" href="#opposition-to-harmony" aria-label="Permalink to &quot;Opposition to &quot;Harmony&quot;&quot;">​</a></h3><p>Central to The Bloc&#39;s worldview is opposition to what they call &quot;Harmony&quot;—not only the pharmaceutical product but a broader program they allege involves multiple corporations working toward &quot;sedation, unification, homogeny, and control.&quot;</p><p>The <em>G</em>BOY Manifesto* articulates this philosophy: &quot;This unification, this slow draw to the hive, is not just a natural byproduct of faster information delivery and larger &#39;community&#39; formation. There is a purposeful effort to morph the many into one.&quot;</p><h3 id="resistance-through-symbolism" tabindex="-1">Resistance through symbolism <a class="header-anchor" href="#resistance-through-symbolism" aria-label="Permalink to &quot;Resistance through symbolism&quot;">​</a></h3><p>The Bloc emphasizes memetic and symbolic warfare over physical confrontation. The adoption of G*BOY as a symbol reflects their belief that icons and images can inspire resistance and &quot;awaken&quot; individuals to hidden control mechanisms.</p><p>The manifesto&#39;s subtitle—&quot;Sigils, Symbols, and Memetic Rebellion in the Age of Coercive Homogeny&quot;—captures this approach to activism.</p><h3 id="decentralization-and-autonomy" tabindex="-1">Decentralization and autonomy <a class="header-anchor" href="#decentralization-and-autonomy" aria-label="Permalink to &quot;Decentralization and autonomy&quot;">​</a></h3><p>The organization rejects centralized authority and hierarchical structure, positioning itself as a collective of autonomous individuals united by shared purpose rather than top-down command. This philosophy extends to their operational model and recruitment practices.</p><h2 id="cultural-impact" tabindex="-1">Cultural impact <a class="header-anchor" href="#cultural-impact" aria-label="Permalink to &quot;Cultural impact&quot;">​</a></h2><h3 id="g-boy-as-resistance-icon" tabindex="-1">G*BOY as resistance icon <a class="header-anchor" href="#g-boy-as-resistance-icon" aria-label="Permalink to &quot;G*BOY as resistance icon&quot;">​</a></h3><p>The Bloc&#39;s adoption and promotion of G<em>BOY transformed an escaped experimental subject into a symbol recognized beyond Saint Juniper. G</em>BOY imagery appears in community artwork, online forums, and countercultural spaces as a representation of resistance against institutional control.</p><p>The figure&#39;s red hood has become associated with The Bloc&#39;s identity, with members and supporters adopting red hood imagery as identification markers.</p><h3 id="influence-on-activism" tabindex="-1">Influence on activism <a class="header-anchor" href="#influence-on-activism" aria-label="Permalink to &quot;Influence on activism&quot;">​</a></h3><p>The Bloc represents a model of activism combining technical expertise (hacking, network security), occult practices (ritual work, symbolic interpretation), and community organizing. This hybrid approach has influenced similar groups investigating alleged corporate and governmental misconduct.</p><h3 id="documentation-and-transparency" tabindex="-1">Documentation and transparency <a class="header-anchor" href="#documentation-and-transparency" aria-label="Permalink to &quot;Documentation and transparency&quot;">​</a></h3><p>The Bloc&#39;s practice of publishing recovered materials has created a public record of documents the organization claims reveal illegal research operations. Whether these materials are authentic or how The Bloc obtained them remains subject to debate, but their publication has shaped public discourse around corporate accountability and research ethics.</p><h2 id="media-coverage-and-public-perception" tabindex="-1">Media coverage and public perception <a class="header-anchor" href="#media-coverage-and-public-perception" aria-label="Permalink to &quot;Media coverage and public perception&quot;">​</a></h2><p>The Bloc has received significant media attention across multiple platforms in late 2025, with coverage ranging from conspiracy theory discussions to financial market analysis.</p><h3 id="snarkcast-coverage" tabindex="-1">SnarkCast Coverage <a class="header-anchor" href="#snarkcast-coverage" aria-label="Permalink to &quot;SnarkCast Coverage&quot;">​</a></h3><p>In November 2025, conspiracy theorist <a href="./../people/Conspirazorg">Conspirazorg</a> discussed The Bloc&#39;s allegations about <a href="./Miter-Corporation">Miter Corporation</a> on the podcast <a href="./SnarkCast">SnarkCast</a>, presenting theories about child experimentation and psychic weapons development. Later that month, <em>SnarkCast</em> host <a href="./../people/Milton-Plumb">Milton Plumb</a> and guest <a href="./../people/Rectford-Shillman">Rectford Shillman</a> characterized The Bloc as &quot;hacktivists&quot; and &quot;terrorists,&quot; warning about the organization&#39;s planned blockchain activities involving <a href="./../subjects/G-BOY">G*BOY</a>.</p><h3 id="gboy-cryptocurrency-launch" tabindex="-1">$GBOY Cryptocurrency Launch <a class="header-anchor" href="#gboy-cryptocurrency-launch" aria-label="Permalink to &quot;$GBOY Cryptocurrency Launch&quot;">​</a></h3><p>In December 2025, The Bloc launched the $GBOY cryptocurrency token, which received analysis on the financial program <a href="./Market-Talk">Market Talk</a>. Anchor <a href="./../people/Denise-Kepler">Denise Kepler</a> identified The Bloc as &quot;a group of people posting pictures of a red-hooded boy trying to make some sort of change,&quot; dismissing the project as unworthy of sustained coverage.</p><p>Analysts <a href="./../people/Cynthia-Milkins">Cynthia Milkins</a> and <a href="./../people/Bradleigh-Font">Bradleigh Font</a> reported on the token&#39;s volatile market performance, with Font noting widespread grassroots marketing including G*BOY stickers appearing on personal property throughout the region.</p><p>The cryptocurrency launch demonstrated The Bloc&#39;s expansion into blockchain-based activism and memetic distribution, though mainstream financial media largely dismissed the project&#39;s long-term viability.</p><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><p>As of 2025, The Bloc remains active in investigating Miter Corporation operations and tracking the whereabouts of G-304 following the escape. The organization continues to maintain its headquarters at the St. Juniper Paranormal Museum and conducts ongoing network security research.</p><p>Recent communications indicate The Bloc is attempting to penetrate additional facility systems and gather intelligence on recapture operations led by <a href="./../people/Agent-K">Agent K</a> and Nocturne Squadron.</p><p>The fate of volunteers who had their memories erased remains a primary concern and motivation for The Bloc&#39;s continuing operations.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../people/Z-L1NE">Z*L1NE</a> — Co-founder and communications specialist</li><li><a href="./../people/1NK">1NK</a> — Co-founder and network security researcher</li><li><a href="./../people/GUMM1">GUMM1</a> — Co-founder and data analyst</li><li><a href="./../people/Magdalena">Magdalena</a> — Museum proprietor and adviser</li><li><a href="./../people/Kai-Shepherd">Kai Shepherd</a> — Catalyst for organization&#39;s formation</li><li><a href="./../locations/Hill-Devil-State-Park">Hill Devil State Park</a> — Site of incident that catalyzed formation</li><li><a href="./../subjects/G-BOY">G*BOY (Subject G-304)</a> — Escaped subject and organizational symbol</li><li><a href="./../concepts/The-Mindverse">The Mindverse</a> — Mental realm network affected by ritual</li><li><a href="./../locations/Shinkai-Metropolis">Shinkai Metropolis</a> — Mind place where G*BOY was displaced by ritual</li><li><a href="./../locations/St-Juniper-Paranormal-Museum">St. Juniper Paranormal Museum</a> — Headquarters location</li><li><a href="./Miter-Corporation">Miter Corporation</a> — Primary investigation target</li><li><a href="./../locations/Saint-Juniper-Research-Campus">Saint Juniper Research Campus</a> — Facility under investigation</li><li><a href="./../people/Agent-K">Agent K</a> — Conducts psychological operations against The Bloc</li><li><a href="./SnarkCast">SnarkCast</a> — Satirical podcast covering The Bloc&#39;s activities</li><li><a href="./Market-Talk">Market Talk</a> — Financial program analyzing $GBOY cryptocurrency</li><li><a href="./../people/Conspirazorg">Conspirazorg</a> — Conspiracy theorist discussing The Bloc&#39;s allegations</li><li><a href="./../people/Milton-Plumb">Milton Plumb</a> — SnarkCast host who labeled The Bloc as terrorists</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li><em>G</em>BOY Manifesto: Sigils, Symbols, and Memetic Rebellion* (1999) — Founding document co-authored by 1NK, Z-L1N3, and GUMM1</li><li>The Bloc origin account and organizational history (late 1990s–1999)</li><li>Recovered Miter Corporation internal documents obtained by The Bloc</li><li>&quot;The Bloc&quot; community documentation (November 2025) — Online communications and member discussions</li><li>Saint Juniper Research Campus broadcast hijacking incident</li><li>Visual documentation of G*BOY memetic distribution campaign</li><li>Magdalena&#39;s occult research contributions to The Bloc operations</li></ol><hr><p><em>This article is part of the Saint Juniper Research Documentation Project</em></p>',107)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
